\[
\frac {d \overline {{x}}}{d t} = \operatorname{Cov} (x, F) + \overline {{\left(\frac {d x}{d t}\right)}} \tag {1}
\]

\[
\frac {\partial F (x ^ {*} , y ; \alpha)}{\partial x} = 0 \tag {2}
\]

\[
x ^ {*} (y, \alpha) = - \frac {F _ {x y}}{F _ {x x}} y - \frac {F _ {x \alpha}}{F _ {x x}} \alpha + C \tag {3}
\]

\[
\frac {d \overline {{x}}}{d t} = - \frac {F _ {x y}}{F _ {x x}} \frac {d \overline {{y}}}{d t} - \frac {F _ {x \alpha}}{F _ {x x}} \frac {d \alpha}{d t} \tag {4}
\]

\[
\frac {d \overline {{x}} _ {\mathrm{evo}}}{d t} = - \frac {F _ {x y}}{F _ {x x}} \frac {d \overline {{y}}}{d t}, \quad \frac {d \overline {{x}} _ {\mathrm{plas}}}{d t} = - \frac {F _ {x \alpha}}{F _ {x x}} \frac {d \alpha}{d t} \tag {5}
\]

\[
\frac {d \overline {{x}}}{d t} = \frac {d \overline {{x}} _ {\mathrm{evo}}}{d t} + \frac {d \overline {{x}} _ {\mathrm{plas}}}{d t} \tag {6}
\]

\[
\frac {d \overline {{x}} _ {\mathrm{evo}}}{d t} = - G _ {y y} \frac {F _ {x y}}{F _ {x x}} \frac {\partial F}{\partial \overline {{y}}} \tag {7}
\]

\[
\Delta \overline {{{x}}} _ {\mathrm{plas}} = - \frac {F _ {x \alpha}}{F _ {x x}} \Delta \alpha \tag {8}
\]

\[
\left. \frac {d \overline {{x}} _ {\mathrm{evo}}}{d t} \right| _ {t = 0 ^ {+}} = - G _ {y y} \frac {F _ {x y} ^ {2}}{F _ {x x}} \Delta \overline {{x}} _ {\mathrm{plas}} \tag {9}
\]

\[
\Delta \overline {{y}} (\infty) = - \frac {F _ {x x} F _ {x y}}{\det H} \Delta \overline {{x}} _ {\mathrm{plas}} \tag {10}
\]

\[
\Delta \overline {{{x}}} _ {\text {total}} = \left(1 + \frac {F _ {x y} ^ {2}}{\det H}\right) \Delta \overline {{{x}}} _ {\text {plas}} \tag {11}
\]

\[
\left| \Delta \overline {{x}} _ {\text {total}} \right| \geq \left| \Delta \overline {{x}} _ {\text {plas}} \right| \tag {12}
\]

\[
\frac {d}{d t} \Delta \overline {{y}} (t) = - \frac {1}{\tau} (\Delta \overline {{y}} (t) - \Delta \overline {{y}} (\infty)) \tag {13}
\]

\[
\tau = - \frac {F _ {x x}}{G _ {y y} \det H} \tag {14}
\]

\[
\Delta \overline {{{y}}} (t) = \Delta \overline {{{y}}} (\infty) \left(1 - e ^ {- \frac {t}{\tau}}\right) \tag {15}
\]

\[
G _ {y y} \simeq \sqrt {\frac {V _ {m}}{\kappa}} = \sqrt {- \frac {V _ {m} F _ {x x}}{\det H}} \tag {16}
\]

\[
\tau = \sqrt {- \frac {F _ {x x}}{V _ {m} \det H}} \tag {17}
\]

\[
F _ {x x} = - (s + c), \quad F _ {y y} = - c, \quad F _ {x y} = c, \quad F _ {x \alpha} = s \tag {19}
\]

\[
\Delta \overline {{{x}}} _ {\mathrm{plas}} = - \frac {s}{- (s + c)} \Delta \alpha = \frac {s}{s + c} \Delta \alpha \tag {21}
\]

\[
\Delta \overline {{{y}}} (\infty) = - \frac {- (s + c) c}{s c} \left(\frac {s}{s + c} \Delta \alpha\right) = \Delta \alpha \tag {22}
\]

\[
\Delta \overline {{{x}}} _ {\mathrm{total}} = \left(1 + \frac {c ^ {2}}{s c}\right) \left(\frac {s}{s + c} \Delta \alpha\right) = \Delta \alpha \tag {23}
\]

\[
\tau = - \frac {F _ {x x}}{G _ {y y} \det H} = \frac {s + c}{G _ {y y} s c} = \frac {1}{G _ {y y}} \left(\frac {1}{s} + \frac {1}{c}\right) \tag {24}
\]

\[
\tau = \sqrt {\frac {1}{V _ {m}} \left(\frac {1}{s} + \frac {1}{c}\right)} \tag {25}
\]

\[
\begin{array}{l} d \left(\frac {\partial F}{\partial x}\right) = \frac {\partial^ {2} F}{\partial x ^ {2}} d x ^ {*} + \frac {\partial^ {2} F}{\partial x \partial y} d y + \frac {\partial^ {2} F}{\partial x \partial \alpha} d \alpha \\ = F _ {x x} d x ^ {*} + F _ {x y} d y + F _ {x \alpha} d \alpha \\ = 0 \tag {S1} \\ \end{array}
\]

\[
d x ^ {*} = - \frac {F _ {x y}}{F _ {x x}} d y - \frac {F _ {x \alpha}}{F _ {x x}} d \alpha \tag {S2}
\]

\[
x ^ {*} (y, \alpha) = - \frac {F _ {x y}}{F _ {x x}} y - \frac {F _ {x \alpha}}{F _ {x x}} \alpha + C \tag {S3}
\]

\[
\frac {\partial x ^ {*}}{\partial y} = - \frac {F _ {x y}}{F _ {x x}}, \quad \frac {\partial x ^ {*}}{\partial \alpha} = - \frac {F _ {x \alpha}}{F _ {x x}} \tag {S4}
\]

\[
\frac {d \overline {{x}}}{d t} = \operatorname{Cov} (x, F) + \overline {{\left(\frac {d x}{d t}\right)}} \tag {S5}
\]

\[
\begin{array}{l} \frac {d x ^ {*}}{d t} = \frac {\partial x ^ {*}}{\partial \alpha} \frac {d \alpha}{d t} \\ = - \frac {F _ {x \alpha}}{F _ {x x}} \frac {d \alpha}{d t} \tag {S6} \\ \end{array}
\]

\[
\overline {{\left(\frac {d x}{d t}\right)}} = - \frac {F _ {x \alpha}}{F _ {x x}} \frac {d \alpha}{d t} \tag {S7}
\]

\[
\begin{array}{l} \operatorname{Cov} (x, F) = \operatorname{Cov} (x ^ {*}, F) \\ = \operatorname{Cov} \left(- \frac {F _ {x y}}{F _ {x x}} y - \frac {F _ {x \alpha}}{F _ {x x}} \alpha + C, F\right) \\ = - \frac {F _ {x y}}{F _ {x x}} \operatorname{Cov} (y, F) \tag {S8} \\ \end{array}
\]

\[
\frac {d \overline {{y}}}{d t} = \operatorname{Cov} (y, F) \tag {S9}
\]

\[
\operatorname{Cov} (x, F) = - \frac {F _ {x y}}{F _ {x x}} \frac {d \overline {{y}}}{d t} \tag {S10}
\]

\[
\frac {d \overline {{x}}}{d t} = - \frac {F _ {x y}}{F _ {x x}} \frac {d \overline {{y}}}{d t} - \frac {F _ {x \alpha}}{F _ {x x}} \frac {d \alpha}{d t} \tag {S11}
\]

\[
\frac {d \overline {{x}} _ {\mathrm{evo}}}{d t} = - \frac {F _ {x y}}{F _ {x x}} \frac {d \overline {{y}}}{d t}, \quad \frac {d \overline {{x}} _ {\mathrm{plas}}}{d t} = - \frac {F _ {x \alpha}}{F _ {x x}} \frac {d \alpha}{d t} \tag {S12}
\]

\[
\frac {d \overline {{x}}}{d t} = \frac {d \overline {{x}} _ {\mathrm{evo}}}{d t} + \frac {d \overline {{x}} _ {\mathrm{plas}}}{d t} \tag {S13}
\]

\[
\begin{array}{l} F (x, y; \alpha) = F (\overline {{x}}, \overline {{y}}; \alpha) + \frac {\partial F}{\partial \overline {{x}}} (x - \overline {{x}}) + \frac {\partial F}{\partial \overline {{y}}} (y - \overline {{y}}) \\ + \frac {1}{2} F _ {x x} (x - \overline {{x}}) ^ {2} + F _ {x y} (x - \overline {{x}}) (y - \overline {{y}}) + \frac {1}{2} F _ {y y} (y - \overline {{y}}) ^ {2} \tag {S14} \\ \end{array}
\]

\[
\begin{array}{l} \operatorname{Cov} (y, F) = \overline {{[ (y - \overline {{y}}) F (x , y ; \alpha) ]}} \\ = F (\overline {{x}}, \overline {{y}}; \alpha) \overline {{(y - \overline {{y}})}} + \frac {\partial F}{\partial \overline {{y}}} \overline {{(y - \overline {{y}}) ^ {2}}} + \frac {1}{2} \left(F _ {y y} - \frac {F _ {x y} ^ {2}}{F _ {x x}}\right) \overline {{(y - \overline {{y}}) ^ {3}}} \\ = \frac {\partial F}{\partial \overline {{y}}} \overline {{(y - \overline {{y}}) ^ {2}}} \\ = G _ {y y} \frac {\partial F}{\partial \overline {{y}}} = \frac {d \overline {{y}}}{d t} \tag {S15} \\ \end{array}
\]

\[
\frac {d \overline {{x}} _ {\mathrm{evo}}}{d t} = - G _ {y y} \frac {F _ {x y}}{F _ {x x}} \frac {\partial F}{\partial \overline {{y}}} \tag {S16}
\]

\[
\begin{array}{l} \Delta \overline {{x}} _ {\mathrm{plas}} = \int_ {- \epsilon} ^ {+ \epsilon} \frac {d \overline {{x}} _ {\mathrm{plas}}}{d t} d t \\ = - \int_ {- \epsilon} ^ {+ \epsilon} \frac {F _ {x \alpha}}{F _ {x x}} \Delta \alpha \delta (t) d t \\ = - \frac {F _ {x \alpha}}{F _ {x x}} \Delta \alpha \tag {S17} \\ \end{array}
\]

\[
\begin{array}{l} \left. \frac {\partial F}{\partial \overline {{y}}} \right| _ {t = 0 ^ {+}} = \left. \frac {\partial F}{\partial \overline {{y}}} \right| _ {t = 0 ^ {-}} + \frac {\partial}{\partial \overline {{x}}} \left(\frac {\partial F}{\partial \overline {{y}}}\right) \Delta \overline {{x}} + \frac {\partial}{\partial \overline {{y}}} \left(\frac {\partial F}{\partial \overline {{y}}}\right) \Delta \overline {{y}} + \frac {\partial}{\partial \alpha} \left(\frac {\partial F}{\partial \overline {{y}}}\right) \Delta \alpha \\ = F _ {x y} \Delta \overline {{x}} + F _ {y y} \Delta \overline {{y}} + F _ {y \alpha} \Delta \alpha \tag {S18} \\ \end{array}
\]

\[
\left. \frac {\partial F}{\partial \overline {{y}}} \right| _ {t = 0 ^ {+}} = F _ {x y} \Delta \overline {{x}} _ {\text {plas}} \tag {S19}
\]

\[
\left. \frac {d \overline {{x}} _ {\mathrm{evo}}}{d t} \right| _ {t = 0 ^ {+}} = - G _ {y y} \frac {F _ {x y} ^ {2}}{F _ {x x}} \Delta \overline {{x}} _ {\mathrm{plas}} \tag {S20}
\]

\[
\begin{array}{l} \Delta \overline {{x}} (t) = \int_ {0 ^ {-}} ^ {t} \frac {d \overline {{x}} _ {\mathrm{evo}}}{d t} d t + \int_ {0 ^ {-}} ^ {t} \frac {d \overline {{x}} _ {\mathrm{plas}}}{d t} d t \\ = \Delta \overline {{x}} _ {\mathrm{evo}} (t) + \Delta \overline {{x}} _ {\mathrm{plas}} \\ = - \frac {F _ {x y}}{F _ {x x}} \Delta \overline {{y}} (t) + \Delta \overline {{x}} _ {\mathrm{plas}} \tag {S21} \\ \end{array}
\]

\[
\frac {\partial F}{\partial \overline {{y}}} (t) = F _ {x y} \Delta \overline {{x}} (t) + F _ {y y} \Delta \overline {{y}} (t) \tag {S22}
\]

\[
\begin{array}{l} \frac {\partial F}{\partial \overline {{y}}} (t) = F _ {x y} \left(- \frac {F _ {x y}}{F _ {x x}} \Delta \overline {{y}} (t) + \Delta \overline {{x}} _ {\mathrm{plas}}\right) + F _ {y y} \Delta \overline {{y}} (t) \\ = F _ {x y} \Delta \overline {{x}} _ {\mathrm{plas}} + \left(F _ {y y} - \frac {F _ {x y} ^ {2}}{F _ {x x}}\right) \Delta \overline {{y}} (t) \\ = F _ {x y} \Delta \overline {{x}} _ {\mathrm{plas}} + \frac {\det H}{F _ {x x}} \Delta \overline {{y}} (t) \tag {S23} \\ \end{array}
\]

\[
\Delta \overline {{y}} (\infty) = - \frac {F _ {x x} F _ {x y}}{\det H} \Delta \overline {{x}} _ {\mathrm{plas}} \tag {S24}
\]

\[
\begin{array}{l} \Delta \overline {{x}} _ {\mathrm{total}} = \Delta \overline {{x}} _ {\mathrm{evo}} (\infty) + \Delta \overline {{x}} _ {\mathrm{plas}} \\ = - \frac {F _ {x y}}{F _ {x x}} \Delta \overline {{y}} (\infty) + \Delta \overline {{x}} _ {\mathrm{plas}} \\ = \left(1 + \frac {F _ {x y} ^ {2}}{\det H}\right) \Delta \overline {{x}} _ {\mathrm{plas}} \tag {S25} \\ \end{array}
\]

\[
\begin{array}{l} \frac {d}{d t} \Delta \overline {{y}} (t) = G _ {y y} \left(F _ {x y} \Delta \overline {{x}} _ {\mathrm{plas}} + \frac {\det H}{F _ {x x}} \Delta \overline {{y}} (t)\right) \\ = G _ {y y} \frac {\det H}{F _ {x x}} \Delta \overline {{y}} (t) + G _ {y y} F _ {x y} \Delta \overline {{x}} _ {\mathrm{plas}} \\ = G _ {y y} \frac {\det H}{F _ {x x}} \Delta \overline {{y}} (t) - G _ {y y} \frac {\det H}{F _ {x x}} \Delta \overline {{y}} (\infty) \\ = - \frac {1}{\tau} (\Delta \overline {{y}} (t) - \Delta \overline {{y}} (\infty)) \tag {S26} \\ \end{array}
\]

\[
\frac {\partial^ {2} F}{\partial \overline {{y}} ^ {2}} = \frac {\det H}{F _ {x x}} = - \kappa \tag {S27}
\]

\[
P ^ {\prime} (y) \propto P (y) \exp \left[ - \frac {\kappa}{2} \left(y - y _ {\mathrm{opt}}\right) ^ {2} \right] \tag {S28}
\]

\[
G _ {y y} ^ {\prime} = \frac {G _ {y y}}{1 + \kappa G _ {y y}} \tag {S29}
\]

\[
G _ {y y} = \frac {G _ {y y}}{1 + \kappa G _ {y y}} + V _ {m}
\]

\[
0 = \kappa G _ {y y} ^ {2} - \kappa V _ {m} G _ {y y} - V _ {m}
\]

\[
G _ {y y} = \frac {V _ {m}}{2} + \sqrt {\frac {V _ {m} ^ {2}}{4} + \frac {V _ {m}}{\kappa}} \tag {S30}
\]

\[
G _ {y y} \simeq \sqrt {\frac {V _ {m}}{\kappa}} = \sqrt {- \frac {V _ {m} F _ {x x}}{\det H}} \tag {S31}
\]
